import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{C as t,E as n,M as r,N as i,O as a,P as o,S as s,j as c,k as l,l as u,n as d,o as f,p,t as m,w as h}from"./shared-BLp3PbbW.js";import{t as g}from"./circle-check-DBwwkemi.js";import{t as _}from"./file-text-z34ItJdM.js";import{t as v}from"./CodeEditor-DqHMt3P8.js";var y=e();function b({module:e}){return(0,y.jsxs)(i,{children:[(0,y.jsx)(r,{variant:`project`,chip:e??`Месяц 2 · Блок 8`,title:`Воспроизводимость и передача проекта`,intro:`Persistent Planner уже собран и принят. Подготовим проверяемую версию, которую другой разработчик сможет запустить по README и понять без нашей переписки.`,tags:[{icon:(0,y.jsx)(_,{size:14}),label:`README и чистая копия`},{icon:(0,y.jsx)(g,{size:14}),label:`проверенная передача`}]}),(0,y.jsxs)(o,{number:`00`,title:`От принятого проекта к воспроизводимой передаче`,children:[(0,y.jsx)(a,{children:`К этому шагу у Persistent Planner уже есть Task, два варианта хранения, PlannerService, тонкий CLI и тесты. В предыдущей работе мы прошли сквозной сценарий через CLI, проверили ошибки и восстановление данных новым service. Теперь посмотрим на принятую версию с позиции человека, который получает её из репозитория.`}),(0,y.jsx)(l,{variant:`connected`,items:[{title:`Точка старта`,description:`Приложение и сохранение между процессами уже работают; тесты защищают готовые роли.`},{title:`Новый вопрос`,description:`Сможем ли мы запустить именно эту версию в отдельной копии по одной инструкции?`},{title:`Результат`,description:`README, зависимости, тесты и проверенная версия дают другому разработчику повторяемый путь.`}]}),(0,y.jsx)(`p`,{children:`Представьте, что коллега получил ссылку на Planner, но у него нет вашего виртуального окружения и файла с задачами. Он открывает README и должен узнать, из какого каталога запускать команды, какой Python использовать и как убедиться, что данные пережили завершение программы. Если приходится спрашивать автора о каждом шаге, передача ещё не готова. Проверяем именно возможность повторить результат.`}),(0,y.jsx)(`p`,{children:`В предыдущем занятии мы проверяли действия над задачами и восстановление новым объектом сервиса. Теперь дополнительно нужны другая папка, заново установленная среда и два независимых запуска Python. Эти условия отделяют работу программы от случайно оставшихся файлов и настроек автора. Если подготовка прошлого занятия ещё не завершена, сначала доведите его сквозной сценарий и существующие тесты до принятого результата. Здесь не добавляем новые функции ради красивого релиза.`})]}),(0,y.jsxs)(o,{number:`01`,title:`Чистая копия отделяет исходники от окружения и данных`,children:[(0,y.jsx)(a,{children:`Локальная папка разработчика может содержать больше, чем проект: виртуальное окружение, кэш, личный JSON и незакоммиченные изменения. В отдельной проверочной копии мы видим, какие файлы действительно доступны из выбранной версии репозитория.`}),(0,y.jsx)(`p`,{children:`Разделите содержимое папки на четыре группы. Исходники app/ и тесты tests/ описывают поведение. README.md объясняет действия получателя. requirements-dev.txt перечисляет внешние пакеты для разработки: в принятом проекте это pytest, тогда как обычное приложение опирается на стандартную библиотеку Python. Наконец, data/tasks.json содержит конкретные задачи пользователя. Первые три группы должны соответствовать выбранному коммиту; личный JSON, кэш и .venv получатель не обязан получать из Git.`}),(0,y.jsx)(`p`,{children:`Виртуальное окружение .venv связано с конкретным компьютером и путями к интерпретатору. Его создают заново, а не копируют из папки автора. Отдельная папка тоже может оказаться загрязнённой: если вручную перенести в неё старый tasks.json, первый запуск покажет чужие задачи и скроет ошибку инициализации. Поэтому начинаем с копии выбранного Git-коммита и сначала проверяем отсутствие рабочего файла данных. Никаких удалений в основной папке делать не нужно.`}),(0,y.jsx)(p,{prompt:`Определите, зачем нужен каждый файл. Затем проверьте, какие из них должны быть в репозитории.`,leftTitle:`Файл или каталог`,rightTitle:`Роль`,pairs:[{left:`app/main.py`,right:`Точка входа приложения`},{left:`requirements-dev.txt`,right:`Список пакетов для разработки и тестов`},{left:`.venv/`,right:`Локальная среда, создаваемая заново`},{left:`data/tasks.json`,right:`Пользовательское состояние, которое создаёт CLI`}],explanation:`Код, установка и данные выполняют разные роли. Ошибка в имени модуля мешает запуску; отсутствие .venv решается созданием среды; отсутствие JSON при первом старте означает пустой набор, а не потерю исходников.`}),(0,y.jsx)(n,{tone:`info`,children:`Не удаляем и не подменяем рабочую data/tasks.json. Проверочная копия использует собственный путь данных, а автоматические тесты продолжают работать с tmp_path.`})]}),(0,y.jsxs)(o,{number:`02`,title:`README становится проверяемым маршрутом запуска`,children:[(0,y.jsx)(a,{children:`README нужен человеку до того, как он разобрался в модулях. Его короткий маршрут должен довести от клонирования до наблюдаемого результата без устных пояснений автора.`}),(0,y.jsx)(`p`,{children:`Сначала README называет назначение программы и только реально поддерживаемые команды CLI. Затем указывает проверенную версию Python, корень проекта с каталогами app/ и tests/, способ создания .venv и точные команды установки. Для проверки нужны два разных результата: успешное завершение pytest и открывающееся меню Planner. Команды add, list и done человек вводит уже в меню, а не в PowerShell. Наконец, README объясняет путь JSON, первый пустой запуск, ожидаемые ошибки и пределы файлового хранения.`}),(0,y.jsx)(`p`,{children:`Покажем исполнимый фрагмент для PowerShell. Команда python -m venv .venv создаёт среду, а явный путь к .venv\\Scripts\\python.exe исключает случайный выбор глобального Python. Через тот же интерпретатор мы устанавливаем pytest и запускаем тесты. На Linux и macOS путь обычно .venv/bin/python; этот вариант нужно отдельно указать в README, если вы обещаете поддержку системы. Проверяем каждую строку именно из корня новой копии.`}),(0,y.jsx)(v,{caption:`пример последовательности для PowerShell из корня копии`,code:`python -m venv .venv
.\\.venv\\Scripts\\python.exe -m pip install -r requirements-dev.txt
.\\.venv\\Scripts\\python.exe -c "import sys; print(sys.executable)"
.\\.venv\\Scripts\\python.exe -m pytest
.\\.venv\\Scripts\\python.exe -m app.main
# выйти из CLI, затем в новом терминальном запуске:
.\\.venv\\Scripts\\python.exe -m app.main`}),(0,y.jsx)(`p`,{children:`Обратите внимание на -m: выбранный Python ищет модуль в собственном окружении. Если вместо pytest появляется No module named pytest, это прежде всего вопрос о правильном интерпретаторе и установке пакета, а не причина переписывать тесты. Если No module named app появляется при запуске программы, первым делом сверяем текущий каталог и наличие app/. После первого запуска создайте задачу и завершите меню штатно. Повторная команда должна открыть новый процесс и прочитать данные из той же проверочной копии.`}),(0,y.jsx)(`p`,{children:`README не должен обещать готовый файл data/tasks.json в Git: в чистой копии он появляется по ходу работы приложения. При отсутствующем файле допустим пустой набор, при существующем повреждённом JSON должна появиться ошибка хранения. Второй случай нельзя «лечить» записью пустого списка поверх файла. Для реальной диагностики сохраняем исходные данные и исследуем только копию: важно не потерять то, что уже было записано.`}),(0,y.jsxs)(n,{tone:`info`,children:[`Если нужна точная справка по ключам команды и принципам среды, откройте `,(0,y.jsx)(`a`,{href:`https://docs.python.org/3/library/venv.html`,target:`_blank`,rel:`noreferrer`,children:`документацию Python о venv`}),` и `,(0,y.jsx)(`a`,{href:`https://docs.pytest.org/en/stable/explanation/goodpractices.html`,target:`_blank`,rel:`noreferrer`,children:`рекомендации pytest по запуску тестов`}),`. В README оставьте только команды, проверенные на своём проекте.`]})]}),(0,y.jsxs)(o,{number:`03`,title:`Проверки повторяются в отдельной копии`,children:[(0,y.jsx)(a,{children:`В предыдущей работе тесты уже были добавлены к модели, сервису, storage и CLI. Здесь мы запускаем готовый набор и повторяем пользовательский путь по README, не пишем тестовую систему заново.`}),(0,y.jsx)(`p`,{children:`Проверьте устройство тестов, прежде чем доверять результату. Для файловых сценариев pytest выдаёт тесту временный каталог tmp_path: в нём можно создать отсутствующий, корректный или повреждённый JSON, не меняя личные задачи. Успешная проверка метода storage подтверждает его локальное поведение, но ещё не доказывает, что точка входа использует JsonStorage и правильный путь. Это мы проверим отдельным пользовательским запуском, а не новым автотестом текущего урока.`}),(0,y.jsx)(`p`,{children:`В первом процессе создайте две учебные задачи, одну отметьте выполненной и выйдите из программы. После нового запуска запросите список и статистику. Ожидайте два прежних идентификатора и состояния: all = 2, done = 1, open = 1. Равенство all = done + open проверяет согласованность счётчиков, а сохранённые идентификаторы отличают восстановление старых задач от создания новых при старте. Мы проверяем процесс, потому что новый объект Python в том же процессе мог бы случайно разделять память с прежним объектом.`}),(0,y.jsx)(h,{title:`Упорядочим репетицию передачи`,prompt:`Соберём действия от выбора версии до наблюдаемого результата нового процесса.`,pieces:[{id:`revision`,code:`выбрать и записать проверяемый commit`},{id:`copy`,code:`получить отдельную копию репозитория`},{id:`environment`,code:`создать окружение и установить зависимости по README`},{id:`tests`,code:`запустить описанную команду тестов`},{id:`first-run`,code:`создать и завершить демонстрационную задачу через CLI`},{id:`restart`,code:`открыть новый процесс и проверить восстановленное состояние`}],correctOrder:[`revision`,`copy`,`environment`,`tests`,`first-run`,`restart`],explanation:`Мы сначала определяем исходники и условия запуска, затем проверяем автоматические проверки и отдельный сценарий восстановления.`,incorrectExplanation:`Вернёмся к маршруту по порядку: сначала фиксируем версию и чистую копию, потом окружение, тесты и пользовательский запуск.`}),(0,y.jsx)(s,{statement:(0,y.jsx)(y.Fragment,{children:`Если pytest завершился успешно, восстановление после отдельного запуска CLI уже доказано.`}),isTrue:!1,explanation:`Тесты подтверждают только свои сценарии. Отдельный процесс CLI проверяет, что инструкция запуска и пользовательский путь работают вместе.`}),(0,y.jsx)(`p`,{children:`Ещё одна безопасная проверка касается импорта. Выполните из корня копии команду python -c "import app.main" через интерпретатор новой .venv. Импорт должен завершиться без меню, запроса ввода и записи пользовательского JSON: точка входа запускает цикл только при непосредственном старте модуля. Если меню появляется при импорте, это отдельный дефект точки входа. Если тест прошёл, а второй запуск потерял задачу, сравните пути данных двух процессов, не объявляйте успех по одному зелёному pytest.`})]}),(0,y.jsxs)(o,{number:`04`,title:`Архитектурное объяснение показывает путь одной задачи`,children:[(0,y.jsx)(a,{children:`README отвечает на вопрос «как запустить», а архитектурное объяснение отвечает на вопрос «кто за что отвечает». Проследим одну изменяемую задачу от команды до файла, не пересказывая каждый модуль.`}),(0,y.jsx)(`p`,{children:`CLI разбирает введённую команду и показывает ответ. PlannerService выбирает предметное действие: например, при done ищет задачу по идентификатору, вызывает правило Task.mark_done() и сохраняет изменённый набор. Storage отвечает за load и save: JsonStorage читает и записывает файл, MemoryStorage держит список в памяти для изолированных сценариев. В app/main.py функция сборки выбирает хранилище для обычного запуска; переданный объект позволяет тесту выбрать другое. Это две альтернативные реализации одного договора, а не две синхронные базы.`}),(0,y.jsxs)(m,{caption:`Одна команда проходит через предметный слой к выбранному файлу`,children:[(0,y.jsxs)(f,{label:`Команда и правила одной задачи`,children:[(0,y.jsx)(u,{title:`CLI`,shape:`process`,children:(0,y.jsx)(`p`,{children:`Принимает команду и показывает результат`})}),(0,y.jsx)(d,{label:`команда и аргументы`}),(0,y.jsx)(u,{title:`PlannerService`,children:(0,y.jsx)(`p`,{children:`Координирует действие над актуальным набором`})}),(0,y.jsx)(d,{label:`использует`}),(0,y.jsx)(u,{title:`Task`,children:(0,y.jsx)(`p`,{children:`Хранит состояние и проверяет правила одной задачи`})})]}),(0,y.jsxs)(f,{label:`Загрузка и сохранение набора`,children:[(0,y.jsx)(u,{title:`PlannerService`,children:(0,y.jsx)(`p`,{children:`Запрашивает набор для действия`})}),(0,y.jsx)(d,{label:`load / save`}),(0,y.jsx)(u,{title:`JsonStorage`,shape:`database`,children:(0,y.jsx)(`p`,{children:`Преобразует Task и управляет файловым IO`})}),(0,y.jsx)(d,{label:`читает и записывает`,direction:`both`}),(0,y.jsx)(u,{title:`data/tasks.json`,shape:`database`,children:(0,y.jsx)(`p`,{children:`Внешнее состояние обычного запуска`})})]})]}),(0,y.jsx)(`p`,{children:`Прочитайте схему для двух команд. При list сервис загружает список и отдаёт его CLI; сохранение здесь не нужно, потому что задачи не изменились. При done сервис загружает список, находит нужную Task, меняет состояние через метод модели и только после успешного действия вызывает save. JsonStorage преобразует объекты Task в JSON-записи, а при чтении восстанавливает объекты. Поэтому утверждение «Task сама открывает файл» неверно: правила одной задачи не знают путь на диске.`}),(0,y.jsx)(`p`,{children:`Для контрольного вопроса представьте, что мы заменили JsonStorage на MemoryStorage в сборке теста. Какие файлы нужно исправить, чтобы add_task сохранил работу? Никакие: сервис опирается на одинаковые методы load и save. Но есть тонкость: копирование списка в памяти само по себе не копирует вложенные объекты Task. Это ограничение важно не спутать с независимостью разных задач и их списков tags. Схема объясняет роли, а конкретные тесты проверяют поведение.`}),(0,y.jsx)(n,{tone:`info`,children:`При объяснении сначала назовём наблюдаемое действие, затем владельца правила и сохранения. CLI не открывает JSON, а storage не решает, допустим ли приоритет.`})]}),(0,y.jsxs)(o,{number:`05`,title:`Проверенная версия должна совпасть с передаваемой`,children:[(0,y.jsx)(a,{children:`Результат проверки относится к конкретному состоянию исходников. Если мы запустили тесты на одном состоянии, а передаём другое, зелёный вывод уже не подтверждает переданный код.`}),(0,y.jsx)(`p`,{children:`Commit сохраняет снимок отслеживаемых файлов в истории Git и имеет собственный SHA. Команда git rev-parse HEAD показывает SHA текущего commit, а git status --short помогает увидеть незакоммиченные изменения. Git-тег даёт человеку короткое имя нужному commit, например v1.0.0. GitHub Release добавляет к версии опубликованное описание и, при необходимости, файлы для скачивания. Ни имя тега, ни публикация описания сами по себе не запускают тесты и не включают сервер.`}),(0,y.jsx)(`p`,{children:`Перед выбором версии выполните git status --short и git diff: первая команда перечисляет изменённые пути, вторая показывает содержательные правки отслеживаемых файлов. Проверьте, что README и зависимости отражены в выбранном commit. Если изменения ещё не зафиксированы, старый SHA не подтверждает обновлённую инструкцию: сначала закончите нужную фиксацию и затем проверяйте её в отдельной копии. Если подходящий commit уже есть и дерево чистое, пустой commit создавать не нужно. Не включайте .venv, кэш, секреты или рабочий JSON в проверяемый снимок.`}),(0,y.jsx)(t,{code:`git rev-parse HEAD
python -m pytest -q
# app/storage.py изменён и не включён в commit`,question:`Какое утверждение пока нельзя подтвердить этим запуском?`,options:[`Тесты завершились на рабочей копии`,`Результат относится точно к commit из HEAD`,`Выбранный Python запустил pytest`],correctIndex:1,explanation:`Тесты увидели ещё и локальное изменение app/storage.py. Записанный HEAD не описывает всё проверенное состояние, пока изменение не устранено или не включено в отдельную проверяемую версию.`}),(0,y.jsx)(`p`,{children:`Для отдельной копии можно использовать git clone с локальным адресом исходного репозитория, затем git checkout выбранного SHA. Если используете удалённый источник, сначала убедитесь, что этот commit туда действительно отправлен. В копии повторно выполните git rev-parse HEAD и git status --short: SHA должен совпасть, дерево должно быть чистым. Теперь вывод pytest и наблюдение двух процессов относятся к определённой версии. В заметке передачи запишите фактические команды и результаты, не только фразу «у меня работает».`}),(0,y.jsxs)(n,{tone:`info`,children:[`Сверить команды и значения статусов можно в справке Git: `,(0,y.jsx)(`a`,{href:`https://git-scm.com/docs/git-status`,target:`_blank`,rel:`noreferrer`,children:`git status`}),` и `,(0,y.jsx)(`a`,{href:`https://git-scm.com/docs/git-clone`,target:`_blank`,rel:`noreferrer`,children:`git clone`}),`. Проверьте вывод на своей копии до записи SHA в отчёт.`]})]}),(0,y.jsxs)(o,{number:`06`,title:`Передача включает ограничения и короткую демонстрацию`,children:[(0,y.jsx)(a,{children:`Новому разработчику важны не только успешные команды. Ему нужно знать, где появляются данные, что приложение не гарантирует и как локализовать ожидаемый отказ.`}),(0,y.jsx)(`p`,{children:`Ограничения надо объяснять через последствия. Один JSON-файл подходит для учебного последовательного запуска, но текущая запись полного снимка не обещает атомарность: при сбое во время записи данные могут быть повреждены. Два одновременно работающих процесса не согласуют изменения и могут перезаписать результаты друг друга. Если файл существует, но повреждён, storage должен сообщить об ошибке, а не заменить данные пустым списком. Эту ситуацию изучают только на отдельной копии файла.`}),(0,y.jsx)(`p`,{children:`Если проверка не прошла, в отчёте укажите команду, фактическое сообщение, ожидаемый результат, причину после диагностики и результат повторной проверки. No module named pytest сначала ведёт к выбранному Python; No module named app ведёт к текущей папке; пустой список во втором процессе ведёт к пути JSON и точке сборки. Ошибка StorageError ведёт к сохранению повреждённого файла и исследованию его копии. Разные симптомы требуют разных первых шагов: без этого «попробуйте переустановить всё» не является помощью.`}),(0,y.jsxs)(n,{tone:`info`,children:[`Защита занимает около пяти минут: назовите назначение и проверенный SHA, покажите путь одной задачи через два процесса, объясните роли CLI → service → Task/storage, приведите результат pytest и одно честное ограничение. Черновик release notes должен перечислять возможности, способ проверки и границы. Tag, GitHub Release и развёртывание не выполняются автоматически и не требуются для зачёта этого урока. Для сравнения прочитайте `,(0,y.jsx)(`a`,{href:`https://docs.github.com/en/repositories/releasing-projects-on-github/about-releases`,target:`_blank`,rel:`noreferrer`,children:`описание GitHub Releases`}),`.`]})]}),(0,y.jsxs)(o,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(a,{children:`Практика принимает готовый Persistent Planner и проверенную версию как исходную точку. Мы не добавляем CRUD, новые тесты или слой архитектуры. Мы проверяем, можно ли передать проект по документированному маршруту.`}),(0,y.jsx)(l,{variant:`connected`,items:[{title:`Уточним README`,description:`Команды установки, тестов и запуска приводят к наблюдаемому результату из корня проекта.`},{title:`Повторим чистый запуск`,description:`Отдельная копия получает зависимости по инструкции и проходит существующий набор тестов.`},{title:`Подтвердим результат и границы`,description:`Два процесса сохраняют идентификаторы и статусы; отчёт называет commit, роли компонентов и ограничения JSON.`}]}),(0,y.jsx)(`p`,{children:`В практике вы сами напишете README, сверите роли компонентов, выберете commit и подтвердите его из другой папки. Потом создадите в первом процессе две задачи, измените одну и восстановите оба состояния во втором. Для каждого ключевого действия сохраните команду, результат и SHA. Если возникнет дефект, исправьте источник проблемы и повторите соответствующий шаг: пустой файл данных в новой копии допустим, а неожиданно пустой набор после сохранения требует проверки.`}),(0,y.jsx)(`p`,{children:`Итогом станет проверяемый комплект для следующего разработчика: README с исполнимыми командами, короткая схема, SHA, результаты тестов и двух запусков, ограничения и черновик release notes. Глава 3 добавит HTTP-интерфейс к тем же предметным компонентам, но здесь API не создаётся. Полезный контроль перед сдачей: сможет ли человек по вашей инструкции повторить путь, не видя вашего терминала и не получив ваш личный JSON?`}),(0,y.jsx)(c,{text:`Передайте готовый Persistent Planner так, чтобы другой разработчик смог повторить запуск и понять подтверждённые границы.`})]})]})}export{b as Lesson40_1};